function pairQuiz(pairs, chapterIndex, askMeaning=true){
 const bank=pairs.length>=20?pairs.slice(0,20):pairs;
 return Array.from({length:20},(_,i)=>{
  const p=bank[i%bank.length], distractors=[1,2,3].map(k=>bank[(i+k+1)%bank.length][1]);
  const opts=[p[1],...distractors],rot=(i+chapterIndex)%4,choices=opts.map((_,j)=>opts[(j+rot)%4]);
  return [askMeaning?'What does “'+p[0]+'” mean?':'Choose the correct meaning of “'+p[0]+'”.',choices,(4-rot)%4,'“'+p[0]+'” means “'+p[1]+'”. Choose the meaning that fits the expression and its context.'];
 });
}
